using System;using System.IO;using System.Collections.Generic;using ScoreModern.RecoveredFragments;
class InputChordLayoutProof{
 static int Main(string[] a){try{byte[] ds=File.ReadAllBytes(a[0]),ss=File.ReadAllBytes(a[1]),before=File.ReadAllBytes(a[2]),after=File.ReadAllBytes(a[3]),ads=File.ReadAllBytes(a[4]);int sp=int.Parse(a[5]),endOff=BitConverter.ToUInt16(ss,sp+4),spanOff=BitConverter.ToUInt16(ss,sp+8),end=BitConverter.ToInt16(ds,endOff),start=(short)Math.Truncate(end-Math.Abs(BitConverter.ToSingle(ds,spanOff))),count=BitConverter.ToInt16(ds,0x8798);var rows=new List<float[]>();for(int i=0;i<count;i++){var p=new float[15];Buffer.BlockCopy(before,i*60,p,0,60);rows.Add(p);}int returned=InputChordLayout.Apply(rows,start-1,end-1);if(returned!=BitConverter.ToInt16(ads,endOff))throw new Exception("Endpoint argument "+returned+" != "+BitConverter.ToInt16(ads,endOff));int checks=0;for(int i=0;i<count;i++)for(int p=0;p<15;p++){if(BitConverter.ToInt32(BitConverter.GetBytes(rows[i][p]),0)!=BitConverter.ToInt32(after,i*60+p*4))throw new Exception("Record "+i+" P"+(p+1)+": "+rows[i][p]+" != "+BitConverter.ToSingle(after,i*60+p*4));checks++;}Console.WriteLine("PASS "+checks+" original chord-layout words and returned endpoint argument, range "+start+".."+end);return 0;}catch(Exception e){Console.Error.WriteLine(e);return 1;}}
}
